mapper.select:


    deleted_flag = 'N'
    and flowFormBind.flow_code = #{flowCode}
    and flowFormBind.flow_name like concat('%', #{flowName}, '%')
    and flowFormBind.table_code = #{tableCode}
    and flowFormBind.form_name like concat('%', #{formName}, '%')

order by flowFormBind.created_time desc
